def subgroup_error_rates(y_true, y_pred, groups):
    '''Error rate per group {group: errors / count}; ValueError on length mismatch.'''
    y_true = list(y_true)
    y_pred = list(y_pred)
    groups = list(groups)
    if not (len(y_true) == len(y_pred) == len(groups)):
        raise ValueError('y_true, y_pred and groups must have equal length')
    stats = {}
    for t, p, g in zip(y_true, y_pred, groups):
        if g not in stats:
            stats[g] = [0, 0]
        stats[g][1] += 1
        if t != p:
            stats[g][0] += 1
    return {g: errors / total for g, (errors, total) in stats.items()}

